  .pbh-sub, .pbh-body, .pr-more, .fl-label { font-size: 14px; line-height: 22px; }
  .pbh-link, .pbf-h { font-size: 16px; line-height: 22px; }
  .rs.pr.pr, .rs.pr.pr > .fx { background: #0065B3; }
  .pr-head { display: flex; flex-direction: column; gap: 10px; }
